    int n = 0;
    std::cin >> n;
    std::vector<int> stack;
    for (int i = 0; i < n; i++) {
        std::string op;
        std::cin >> op;
        if (op == "push") {
            int value = 0;
            std::cin >> value;
            stack.push_back(value);
        } else if (op == "pop") {
            stack.pop_back();
        }
    }
    for (std::size_t i = 0; i < stack.size(); i++) {
        if (i > 0) {
            std::cout << " ";
        }
        std::cout << stack[i];
    }
    std::cout << std::endl;
    return 0;
}

